CREATE OR REPLACE FUNCTION "trg_flashcard_redraw_machine"() RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD."redraw" = NEW."redraw" THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW."redraw" <> 'settled' THEN
      RAISE EXCEPTION 'new % must start in initial state % (got %)', 'flashcard', 'settled', NEW."redraw" USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    IF OLD."redraw" = 'settled' THEN

      IF NEW."redraw" = 'drawing' THEN
        IF (EXISTS (SELECT 1 FROM card_art a WHERE a.id = NEW.id || ':3' AND a.status IN ('drawn', 'failed', 'unknown'))) IS NOT TRUE THEN
          RAISE EXCEPTION 'guard failed on % transition from % to %', 'flashcard', 'settled', 'drawing' USING ERRCODE = 'check_violation';
        END IF;        UPDATE "card_art" SET "status" = 'waiting', "description" = NEW.description, "redraws" = redraws + 1 WHERE id = NEW.id || ':3' AND status IN ('drawn', 'failed', 'unknown');
        UPDATE "card_art" SET "status" = 'pending' WHERE id = NEW.id || ':3' AND status = 'waiting';
        RETURN NEW;
      END IF;
      RAISE EXCEPTION 'invalid transition on % from % to %', 'flashcard', OLD."redraw", NEW."redraw" USING ERRCODE = 'check_violation';
    END IF;
    IF OLD."redraw" = 'drawing' THEN

      IF NEW."redraw" = 'settled' THEN

        RETURN NEW;
      END IF;
      RAISE EXCEPTION 'invalid transition on % from % to %', 'flashcard', OLD."redraw", NEW."redraw" USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  RETURN NEW;
END $$;

